        }
        for (platform in NDPlatform.entries) {
            for (density in NDDensity.entries) assertTrue(NDMetrics.resolve(platform, density).sizeTargetMin > 0f)
            for (role in NDTypeRole.entries) assertTrue(NDTextStyle.resolve(role, platform).size > 0f)
        }
    }

    @Test
