        assertEquals(NDColor(0xFFF1F1F1.toInt()), colors.surfaceBase)
        assertEquals(48.0f, NDMetrics.resolve(NDPlatform.Android, NDDensity.Comfortable).sizeTargetMin)
        assertEquals(0L, NDDurations.durationUi(NDMotion.Reduced))
    }

    @Test
